package com.example.pryanik;

import com.example.pryanik.commands.*;
import org.bukkit.*;
import org.bukkit.entity.*;
import org.bukkit.event.*;
import org.bukkit.event.player.*;
import org.bukkit.event.player.PlayerPortalEvent;
import org.bukkit.event.player.PlayerTeleportEvent;
import org.bukkit.event.entity.*;
import org.bukkit.event.block.*;
import org.bukkit.event.inventory.*;
import org.bukkit.plugin.java.JavaPlugin;
import org.bukkit.scoreboard.*;
import java.util.*;

public final class PryanikPlugin extends JavaPlugin implements Listener {
    private Database db;
    private GameModes gameModes;
    private GameStateManager gameStateManager;
    public GameModes gameModes(){return gameModes;}
    public GameStateManager gameStateManager(){return gameStateManager;}
    public String clanScope(Player p){String id=gameModes==null?null:gameModes.instanceOf(p.getWorld().getName());return id==null?(gameModes!=null&&gameModes.isLobby(p.getWorld())?"lobby":"legacy"):id;}
    private final Set<UUID> auth=new HashSet<>(),afk=new HashSet<>(),van=new HashSet<>();
    private final Map<UUID,Long> protection=new HashMap<>(); private final Set<UUID> exemptDamage=new HashSet<>();
    private final Map<UUID,org.bukkit.scheduler.BukkitTask> authTimeouts=new HashMap<>();
    private final Map<UUID,UUID> requests=new HashMap<>(), replies=new HashMap<>();
    public Database db(){return db;} public boolean authed(UUID id){return auth.contains(id);} public boolean afk(UUID id){return afk.contains(id);} public boolean van(UUID id){return van.contains(id);}
    public void authenticate(Player p){UUID id=p.getUniqueId();auth.add(id);exemptDamage.remove(id);protection.remove(id);org.bukkit.scheduler.BukkitTask timeout=authTimeouts.remove(id);if(timeout!=null)timeout.cancel();restore(p);if(gameModes!=null&&gameModes.isLobby(p.getWorld()))Bukkit.getScheduler().runTaskLater(this,()->{if(p.isOnline()&&gameModes.isLobby(p.getWorld()))gameModes.giveLobbyCompass(p);},2L);p.setPlayerListName(p.getName());p.sendMessage("§aВход выполнен.");updateRank(p);}
    public void updateRank(Player p){try{Rank r=db.rank(p.getUniqueId());Scoreboard b=Bukkit.getScoreboardManager().getMainScoreboard();String key=r.name();Team t=b.getTeam(key);if(t==null)t=b.registerNewTeam(key);t.setPrefix(r.prefix()+" §f");for(Team other:b.getTeams())if(other!=t)other.removeEntry(p.getName());t.addEntry(p.getName());Objective health=b.getObjective("pp_health");if(health==null)health=b.registerNewObjective("pp_health","health","§c❤");health.setDisplaySlot(DisplaySlot.BELOW_NAME);p.setScoreboard(b);p.setPlayerListName(r.prefix()+" §f"+p.getName());}catch(Exception ignored){}}
    public void refreshLobbyPlayer(Player p){if(gameModes!=null&&gameModes.isLobby(p.getWorld())){p.setGameMode(GameMode.ADVENTURE);p.setInvulnerable(true);p.setFallDistance(0);p.setFireTicks(0);}else p.setInvulnerable(afk(p.getUniqueId())||van(p.getUniqueId()));} public void hide(Player p){p.setInvulnerable(true);p.setSilent(true);p.setCollidable(false);p.setInvisible(true);p.setSleepingIgnored(true);for(Player v:Bukkit.getOnlinePlayers())if(v!=p)v.hidePlayer(this,p);}
    public void restore(Player p){boolean hidden=afk(p.getUniqueId())||van(p.getUniqueId());p.setInvulnerable(hidden||(gameModes!=null&&gameModes.isLobby(p.getWorld())));p.setSilent(hidden);p.setCollidable(!hidden);p.setInvisible(hidden);for(Player v:Bukkit.getOnlinePlayers())if(v!=p){if(hidden)v.hidePlayer(this,p);else v.showPlayer(this,p);}if(hidden)p.setPlayerListName("§0");}
    public boolean toggleAfk(Player p){if(afk(p.getUniqueId()))afk.remove(p.getUniqueId());else afk.add(p.getUniqueId());restore(p);return afk(p.getUniqueId());}
    public boolean toggleVan(Player p,boolean enabled){if(enabled)van.add(p.getUniqueId());else van.remove(p.getUniqueId());restore(p);return enabled;}
    public UUID takeRequest(UUID id){return requests.remove(id);}public void putRequest(UUID target,UUID sender){requests.put(target,sender);}public UUID replyTarget(UUID id){return replies.get(id);}public void setReply(UUID a,UUID b){replies.put(a,b);}
    @Override public void onEnable(){saveDefaultConfig();db=new Database(this);getServer().getPluginManager().registerEvents(this,this);gameModes=new GameModes(this);getServer().getPluginManager().registerEvents(gameModes,this);gameStateManager=new GameStateManager(this);getServer().getPluginManager().registerEvents(gameStateManager,this);setupHealthDisplay();loadManagedWorlds();gameModes.refreshIndex();gameModes.ensureLobby();Bukkit.getScheduler().runTask(this,gameModes::configureAllLobbyPlayers);if(gameModes.lobby()==null){getLogger().severe("Required lobby world could not be loaded; disabling PryanikPlugin to prevent unsafe joins.");getServer().getPluginManager().disablePlugin(this);return;}if(getServer().getPluginManager().getPlugin("Multiverse-Core")!=null)getLogger().info("Multiverse-Core found; worlds managed by Bukkit/MV are available through /world and /mv.");else getLogger().info("Multiverse-Core not found; built-in Bukkit world management remains available.");for(String name:List.of("reg","register","l","login","setrank","fly","van","afk","tpa","tpaap","tapde","tpablock","msg","r","privat","clan","home","chome","chprivat","chprivatdelete","clanset","world","report","code","mode","lobby")){var c=getCommand(name);if(c!=null){if(name.equals("lobby")){c.setExecutor((sender,cmd,label,args)->{if(!(sender instanceof Player player)){sender.sendMessage("Только игрок.");return true;}if(!authed(player.getUniqueId())){player.sendMessage("§cСначала войдите.");return true;}gameModes.goHub(player);return true;});}else if(name.equals("mode")){ var command=new GameModeCommand(this);c.setExecutor(command);getServer().getPluginManager().registerEvents(command,this);}else if(name.equals("code")){ c.setExecutor(new CodeCommand(this));}else if(name.equals("report")){var command=new ReportCommand(this);c.setExecutor(command);getServer().getPluginManager().registerEvents(command,this);}else if(name.equals("world")){ var command=new WorldCommand(this);c.setExecutor(command);c.setTabCompleter(command);getServer().getPluginManager().registerEvents(command,this);}else if(name.equals("clanset")){ c.setExecutor(new ClanSetCommand(this));}else if(name.equals("privat")){ var command=new PrivatCommand(this);c.setExecutor(command);c.setTabCompleter(command);}else if(name.equals("clan")){var command=new ClanCommand(this);c.setExecutor(command);getServer().getPluginManager().registerEvents(command,this);}else if(name.equals("home")||name.equals("chome")){c.setExecutor(new HomeCommand(this,name));}else if(name.equals("chprivat")||name.equals("chprivatdelete")){c.setExecutor(new ClanPrivateCommand(this,name.equals("chprivatdelete")));}else{var command=new AuthCommands(this,name);c.setExecutor(command);c.setTabCompleter(command);}}}}
    public int modeCount(String mode){return gameModes.count(mode);} public int modeCapacity(String mode){return gameModes.capacity(mode);} public int instanceOnline(String id){return gameModes.online(id);} public String playerSavedWorld(UUID id){try{String[] position=db.position(id);return position==null?null:position[0];}catch(Exception e){return null;}} public String[] savedPosition(UUID id){try{return db.position(id);}catch(Exception e){return null;}} public String instanceOf(String world){return gameModes.instanceOf(world);} public World lobby(){return gameModes.lobby();} public void enterInstance(Player p,String mode,int no){gameModes.enter(p,mode,no);} public void banHardcore(UUID id,String instance){gameModes.banHardcore(id,instance);}
     private void loadExistingManagedWorld(String name,World.Environment env){if(Bukkit.getWorld(name)!=null)return;java.io.File folder=new java.io.File(Bukkit.getWorldContainer(),name);if(!folder.exists()){getLogger().warning("Managed world folder missing; not creating a replacement: "+name);return;}if(!new java.io.File(folder,"level.dat").isFile()){getLogger().severe("Managed world folder has no level.dat; refusing to overwrite: "+name);return;}World loaded=Bukkit.createWorld(new WorldCreator(name).environment(env));if(loaded==null)getLogger().severe("Could not load existing managed world: "+name);else getLogger().info("Loaded existing managed world: "+name);} private void setupHealthDisplay(){Scoreboard board=Bukkit.getScoreboardManager().getMainScoreboard();Objective objective=board.getObjective("pp_health");if(objective==null)objective=board.registerNewObjective("pp_health","health","§c❤");objective.setDisplaySlot(DisplaySlot.BELOW_NAME);for(Player player:Bukkit.getOnlinePlayers())player.setScoreboard(board);} private void loadManagedWorlds(){try{for(String[] instance:db.gameInstances()){String base=instance[2];String[] names={base,base+"_nether",base+"_the_end"};World.Environment[] envs={World.Environment.NORMAL,World.Environment.NETHER,World.Environment.THE_END};for(int i=0;i<3;i++)loadExistingManagedWorld(names[i],envs[i]);}for(String[] set:db.managedWorldSets()){String[] names={set[1],set[2],set[3]};World.Environment[] envs={World.Environment.NORMAL,World.Environment.NETHER,World.Environment.THE_END};for(int i=0;i<3;i++)loadExistingManagedWorld(names[i],envs[i]);}for(String[] entry:db.managedWorlds()){if(Bukkit.getWorld(entry[0])!=null)continue;World.Environment env=switch(entry[1].toUpperCase(Locale.ROOT)){case "NETHER"->World.Environment.NETHER;case "THE_END"->World.Environment.THE_END;default->World.Environment.NORMAL;};World loaded=Bukkit.createWorld(new WorldCreator(entry[0]).environment(env));if(loaded==null)getLogger().warning("Could not load plugin-managed world: "+entry[0]);else getLogger().info("Loaded plugin-managed world: "+entry[0]);}}catch(Exception e){getLogger().severe("Could not load managed worlds from PostgreSQL: "+e.getMessage());}}
    @Override public void onDisable(){if(db!=null)db.close();}
    private void startAuthTimeout(Player player){UUID id=player.getUniqueId();org.bukkit.scheduler.BukkitTask old=authTimeouts.remove(id);if(old!=null)old.cancel();boolean registered;try{registered=db.exists(id);}catch(Exception ex){getLogger().warning("Could not check registration state for "+player.getName()+": "+ex.getMessage());player.kickPlayer("§cНе удалось проверить аккаунт. Попробуйте позже.");return;}String prompt=registered?"§eВы уже зарегистрированы. Войдите: §f/l [пароль]":"§eЗарегистрируйтесь: §f/reg [пароль]";player.sendMessage(prompt);final int[] seconds={0};org.bukkit.scheduler.BukkitTask task=Bukkit.getScheduler().runTaskTimer(this,()->{if(!player.isOnline()||authed(id)){org.bukkit.scheduler.BukkitTask taskRef=authTimeouts.remove(id);if(taskRef!=null)taskRef.cancel();return;}seconds[0]+=5;if(seconds[0]>=60){authTimeouts.remove(id);player.kickPlayer("§cВремя на авторизацию истекло.");return;}player.sendMessage(prompt);},100L,100L);authTimeouts.put(id,task);} @EventHandler public void onJoinScoreboard(PlayerJoinEvent e){e.getPlayer().setScoreboard(Bukkit.getScoreboardManager().getMainScoreboard());} @EventHandler(priority=EventPriority.HIGHEST,ignoreCancelled=true) public void allowInstanceTravel(PlayerTeleportEvent e){if(gameModes!=null&&!gameModes.mayTeleport(e.getPlayer(),e.getTo())){e.setCancelled(true);e.getPlayer().sendMessage("§cВ этот хардкорный гриф вам нельзя возвращаться после смерти.");}} @EventHandler(priority=EventPriority.HIGHEST) public void linkedPortal(PlayerPortalEvent e){if(e.getCause()!=PlayerTeleportEvent.TeleportCause.NETHER_PORTAL&&e.getCause()!=PlayerTeleportEvent.TeleportCause.END_PORTAL)return;World from=e.getFrom().getWorld();if(from==null)return;try{String[] set=db.worldSetFor(from.getName());if(set==null)return;String targetName;if(e.getCause()==PlayerTeleportEvent.TeleportCause.NETHER_PORTAL)targetName=from.getEnvironment()==World.Environment.NETHER?set[1]:set[2];else targetName=from.getEnvironment()==World.Environment.THE_END?set[1]:set[3];World target=Bukkit.getWorld(targetName);if(target==null){World.Environment env=targetName.equals(set[1])?World.Environment.NORMAL:targetName.equals(set[2])?World.Environment.NETHER:World.Environment.THE_END;target=Bukkit.createWorld(new WorldCreator(targetName).environment(env));}if(target==null){e.setCancelled(true);e.getPlayer().sendMessage("§cНе удалось загрузить измерение "+targetName);return;}Location original=e.getTo()==null?target.getSpawnLocation():e.getTo();double x=original.getX(),z=original.getZ();if(e.getCause()==PlayerTeleportEvent.TeleportCause.NETHER_PORTAL&&from.getEnvironment()!=World.Environment.NETHER){x/=8.0;z/=8.0;}else if(e.getCause()==PlayerTeleportEvent.TeleportCause.NETHER_PORTAL){x*=8.0;z*=8.0;}int y=Math.max(target.getMinHeight()+1,Math.min(target.getMaxHeight()-2,original.getBlockY()));e.setTo(new Location(target,x,y,z,original.getYaw(),original.getPitch()));}catch(Exception ex){getLogger().warning("Linked portal routing failed: "+ex.getMessage());}} @EventHandler public void join(PlayerJoinEvent e){Player p=e.getPlayer();try{db.recordPlayerSeen(p.getUniqueId(),p.getName());}catch(Exception ex){getLogger().warning("Could not update report player history: "+ex.getMessage());}auth.remove(p.getUniqueId());hide(p);startAuthTimeout(p);p.setPlayerListName("§0");for(Player v:Bukkit.getOnlinePlayers())if(v!=p&&!auth.contains(v.getUniqueId()))p.hidePlayer(this,v);e.setJoinMessage(null);String joinWorld=getConfig().getString("join-world","");if(!joinWorld.isBlank())getServer().getScheduler().runTask(this,()->{if(!p.isOnline())return;World target=Bukkit.getWorld(joinWorld);if(target==null){getLogger().warning("Configured join-world '"+joinWorld+"' is not loaded.");return;}p.teleport(target.getSpawnLocation());});}
    @EventHandler public void quit(PlayerQuitEvent e){UUID id=e.getPlayer().getUniqueId();protection.remove(id);exemptDamage.remove(id);org.bukkit.scheduler.BukkitTask authTask=authTimeouts.remove(id);if(authTask!=null)authTask.cancel();auth.remove(id);afk.remove(id);van.remove(id);requests.remove(id);e.setQuitMessage(null);}
    @EventHandler public void move(PlayerMoveEvent e){Player p=e.getPlayer();UUID id=p.getUniqueId();if(!authed(id)||afk(id)){ if(e.getTo()!=null&&(e.getFrom().getX()!=e.getTo().getX()||e.getFrom().getZ()!=e.getTo().getZ()||e.getFrom().getY()!=e.getTo().getY())){e.setTo(e.getFrom());if(afk(id))p.sendMessage("§cВы в режиме AFK.");}}}
    @EventHandler(priority=EventPriority.HIGHEST) public void chat(AsyncPlayerChatEvent e){Player sender=e.getPlayer();if(!authed(sender.getUniqueId())){e.setCancelled(true);sender.sendMessage("§cСначала войдите.");return;}if(gameModes==null||gameModes.isLobby(sender.getWorld())){e.setCancelled(true);sender.sendMessage("§cВ лобби чат отключён.");return;}String instance=gameModes.instanceOf(sender.getWorld().getName());if(instance==null){e.setCancelled(true);sender.sendMessage("§cЧат доступен только внутри игрового грифа.");return;}for(Player recipient:new ArrayList<>(e.getRecipients()))if(!instance.equals(gameModes.instanceOf(recipient.getWorld().getName())))e.getRecipients().remove(recipient);try{String pref=db.rank(sender.getUniqueId()).prefix();e.setFormat(pref+" §f%s§7: §f%s");}catch(Exception ignored){}}
    private boolean isCreator(Player p){if(p.hasPermission("pryanik.creator"))return true;try{return db.rank(p.getUniqueId())==Rank.CSRV;}catch(Exception ex){return false;}}
    private static final Set<String> LOBBY_ALLOWED_COMMANDS=Set.of("reg","l");
    @EventHandler(priority=EventPriority.HIGHEST) public void lobbyCommands(PlayerCommandPreprocessEvent e){Player p=e.getPlayer();if(gameModes==null||!gameModes.isLobby(p.getWorld()))return;String message=e.getMessage();String raw=message.length()>1?message.substring(1).split("\\s+",2)[0].toLowerCase(Locale.ROOT):"";if(!LOBBY_ALLOWED_COMMANDS.contains(raw)){e.setCancelled(true);p.sendMessage("§cВ лобби доступны только команды /reg и /l.");}}
     @EventHandler public void hideLobbyCommands(PlayerCommandSendEvent e){Player p=e.getPlayer();if(gameModes==null||!gameModes.isLobby(p.getWorld()))return;e.getCommands().removeIf(cmd->!LOBBY_ALLOWED_COMMANDS.contains(cmd.toLowerCase(Locale.ROOT)));}
    @EventHandler(priority=EventPriority.HIGHEST) public void advancement(org.bukkit.event.player.PlayerAdvancementDoneEvent e){if(gameModes!=null&&gameModes.isLobby(e.getPlayer().getWorld())){try{org.bukkit.advancement.AdvancementProgress progress=e.getPlayer().getAdvancementProgress(e.getAdvancement());for(String criteria:new ArrayList<>(progress.getAwardedCriteria()))progress.revokeCriteria(criteria);}catch(Exception ignored){}}}
    @EventHandler public void interact(PlayerInteractEvent e){if(!authed(e.getPlayer().getUniqueId())||(gameModes!=null&&gameModes.isLobby(e.getPlayer().getWorld())&&!isCreator(e.getPlayer())))e.setCancelled(true);}
    @EventHandler(priority=EventPriority.HIGHEST) public void block(BlockPlaceEvent e){if(!authed(e.getPlayer().getUniqueId())||(gameModes!=null&&gameModes.isLobby(e.getPlayer().getWorld())&&!isCreator(e.getPlayer())))e.setCancelled(true);}
    @EventHandler public void breakBlock(BlockBreakEvent e){if(!authed(e.getPlayer().getUniqueId())||(gameModes!=null&&gameModes.isLobby(e.getPlayer().getWorld())&&!isCreator(e.getPlayer())))e.setCancelled(true);}
    @EventHandler public void inventory(InventoryClickEvent e){if(!(e.getWhoClicked() instanceof Player p))return;if(!authed(p.getUniqueId())){e.setCancelled(true);return;}if(gameModes!=null&&gameModes.isLobby(p.getWorld())&&!isCreator(p)){e.setCancelled(true);return;}if(e.getView().getTitle().equals(GameModeCommand.MENU)||e.getView().getTitle().equals(GameModeCommand.INSTANCES))e.setCancelled(true);}
    @EventHandler(priority=EventPriority.HIGHEST) public void damage(EntityDamageEvent e){if(e.getEntity() instanceof Player p){UUID id=p.getUniqueId();if(gameModes!=null&&gameModes.isLobby(p.getWorld())){e.setCancelled(true);if(e.getCause()==EntityDamageEvent.DamageCause.VOID){p.setInvulnerable(true);p.setHealth(p.getMaxHealth());p.teleport(gameModes.lobby().getSpawnLocation());}if(p.getHealth()<p.getMaxHealth())p.setHealth(p.getMaxHealth());p.setFireTicks(0);p.setFallDistance(0);return;}if(!authed(id)||afk(id)||van(id)||exemptDamage.contains(id)){e.setCancelled(true);}else if(e.getCause()==EntityDamageEvent.DamageCause.VOID&&p.getHealth()<=1.0){World lobby=gameModes==null?null:gameModes.lobby();if(lobby!=null){p.setInvulnerable(true);p.teleport(lobby.getSpawnLocation());p.setHealth(p.getMaxHealth());exemptDamage.add(id);Bukkit.getScheduler().runTaskLater(this,()->{if(p.isOnline()){exemptDamage.remove(id);refreshLobbyPlayer(p);}},40L);}}}}
    @EventHandler public void target(EntityTargetEvent e){if(e.getTarget() instanceof Player p&&(!authed(p.getUniqueId())||afk(p.getUniqueId())||van(p.getUniqueId())))e.setCancelled(true);}
    @EventHandler public void cmd(PlayerCommandPreprocessEvent e){if(!authed(e.getPlayer().getUniqueId())&&!e.getMessage().toLowerCase().startsWith("/reg")&&!e.getMessage().toLowerCase().startsWith("/register")&&!e.getMessage().toLowerCase().startsWith("/l ")&&!e.getMessage().toLowerCase().startsWith("/login ")){e.setCancelled(true);e.getPlayer().sendMessage("§cСначала зарегистрируйтесь или войдите.");}}
}
